x items-center gap-2 text-sm"><input type="hidden" name="isAogHub" value="0"><input type="checkbox" name="isAogHub" value="1" <?= !empty($row['isAogHub']) ? 'checked' : '' ?>> 24/7 AOG dispatch hub</label></div></div>
